 const schema={type:'object',properties:{requiredNull:{type:'null',title:'Required null'},optionalNull:{type:'null',title:'Optional null'},choice:{type:['string','number'],enum:['1','10',0,1,2,true],minLength:2,minimum:1,if:{type:'number'},then:{maximum:1}},values:{type:'array',title:'Values',items:{type:'null',title:'Null entry'}}},required:['requiredNull','choice','values']},form=createRecordEditor({getOperation:'items.get',putOperation:'items.put',jsonSchema:schema}).render({},null,null,document);document.querySelector('main').append(form);const id=form.querySelector('input'),formButton=text=>[...form.querySelectorAll('button')].find(node=>node.textContent===text),status=form.querySelector('[role=status]');id.value='record';id.dispatchEvent(new Event('input',{bubbles:true}));formButton('Load').click();await wait(()=>status.textContent==='Record loaded.');
 const findLabel=text=>[...form.querySelectorAll('label')].find(node=>node.textContent.includes(text)),required=findLabel('Required null (always null)').querySelector('input'),item=findLabel('Values Null entry 1 (always null)').querySelector('input'),optional=findLabel('Include Optional null as null').querySelector('input'),choice=findLabel('choice (required)').querySelector('select');if(!required.checked||!required.disabled||!item.checked||!item.disabled||optional.checked)throw Error('Null field state mismatch');if([...choice.options].some(option=>['Yes (boolean)','1 (text)','0 (number)','2 (number)'].includes(option.textContent)))throw Error('Disallowed choice appeared');optional.checked=true;change(optional);choice.value=[...choice.options].find(option=>option.textContent==='1 (number)').value;change(choice);formButton('Save').click();await wait(()=>calls.length===7&&status.textContent==='Record saved.');if(JSON.stringify(calls[6].value)!==JSON.stringify({requiredNull:null,choice:1,values:[null],optionalNull:null}))throw Error('Null or mixed field save mismatch');
